    // 1. Null checks: If any output pointer is NULL, return error without writing.
    if (momentum == NULL || field == NULL || enabled == NULL || excess == NULL || command == NULL || torque == NULL) {
        return ADCS_E_NULL;
    }

    // 2. Range/Validity checks: Apply regardless of hysteresis state.
    // Check previous_enabled must be 0 or 1.
    if (previous_enabled != 0 && previous_enabled != 1) {
        return ADCS_E_RANGE;
    }
    // Check thresholds are finite and valid order.
    if (!isfinite(start_threshold) || !isfinite(stop_threshold)) {
        return ADCS_E_RANGE;
    }
    if (stop_threshold < 0.0 || stop_threshold >= start_threshold) {
        return ADCS_E_RANGE;
    }
    // Check momentum and field vectors contain finite values.
    if (!adcs_is_finite_vec3(momentum) || !adcs_is_finite_vec3(field)) {
        return ADCS_E_RANGE;
    }

    // 3. Reset all outputs to zero before computing.
    *enabled = 0;
    *excess = 0.0;
    command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
    command->saturated_axes = 0U;
    *torque = (adcs_vec3_t){0.0, 0.0, 0.0};

    // 4. Calculate momentum magnitude.
    double norm = adcs_vec3_norm(momentum);

    // 5. Evaluate hysteresis gate and compute excess->
    int current_enabled = 0;

    // Determine new enabled state based on previous state and norm vs thresholds.
    if (previous_enabled == 0) {
        // Previous was disabled.
        if (norm >= start_threshold) {
            current_enabled = 1;
        } else {
            current_enabled = 0;
        }
    } else {
        // Previous was enabled->
        if (norm > stop_threshold) {
            current_enabled = 1;
        } else {
            current_enabled = 0;
        }
    }
    *enabled = current_enabled;

    // Compute excess basis based on the active threshold.
    if (current_enabled == 1) {
        // Active threshold is stop.
        *excess = norm - stop_threshold;
    } else {
        // Inactive threshold is start.
        double temp = norm - start_threshold;
        if (temp > 0.0) {
            *excess = temp;
        } else {
            *excess = 0.0;
        }
    }

    // 6. Compute bounded magnetic unloading command and achievable torque if enabled->
    if (current_enabled == 1) {
        adcs_status_t status = adcs_momentum_unload_dipole(
            momentum,
            field,
            gain,
            dipole_limit,
            command,
            torque
        );

        // If computation fails, return its status with all outputs zero.
        // Outputs were already zeroed in step 3, so no need to re-zero unless specific fields weren't touched,
        // but the function sets them anyway. The requirement says "all outputs zero".
        // Step 3 already zeroed everything. If adcs_momentum_unload_dipole fails, it might not write to outputs?
        // The prompt says: "if it fails, its status is returned with all outputs zero."
        // Since we zeroed them in step 3, they are already zero. We just return the status.
        if (status != ADCS_OK) {
            return status;
        }
    }

    return ADCS_OK;
}

